#!/bin/sh
apt_menu(){ while :; do c=$(ui_menu APT 'APT repositories and behavior.' config 'Edit apt.conf.d tuning' sources 'Edit sources.list' retries 'Set retries and timeouts' recommends 'Toggle recommends/suggests' cache 'Clean package cache' broken 'Repair broken dependencies' holds 'List package holds' keys 'Inspect keyrings') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in config) edit_file /etc/apt/apt.conf;; sources) edit_file /etc/apt/sources.list;; retries) write_file /etc/apt/apt.conf.d/80ish-aok 644 'Acquire::Retries "5";\nAcquire::http::Timeout "30";\nAcquire::https::Timeout "30";\nAPT::Get::Assume-Yes "false";';; recommends) write_file /etc/apt/apt.conf.d/90ish-aok-minimal 644 'APT::Install-Recommends "false";\nAPT::Install-Suggests "false";';; cache) run_capture 'APT clean' as_root apt-get clean;; broken) run_capture 'APT repair' as_root apt-get -f install;; holds) run_capture Holds apt-mark showhold;; keys) ui_text Keyrings "$(find /etc/apt -type f \( -name '*.gpg' -o -name '*.asc' \) 2>/dev/null)";; esac; done; }
